62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Dedicated audit logger; a successful create emits one line here. */
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /** Dedicated notification logger; a successful create enqueues one welcome line here. */
73	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
74	
75	    /** Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}. */
76	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
77	        new java.util.concurrent.atomic.AtomicLong();
78	
79	    /** Request header carrying the client-supplied key that makes a create idempotent. */
80	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
81	
82	    /**
83	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
84	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
85	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
86	     */
87	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
88	
89	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
90	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
91	
92	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
93	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
94	        "mailinator.com", "tempmail.com", "guerrillamail.com");
95	
96	    /**
97	     * Hard per-city capacity: a create into a city that already holds this many owners is rejected
98	     * with {@code 409 CONFLICT}. Counted against the owners already present, before the new one is
99	     * added, matching the basis of {@link #countOwnersInCity(String)}.
100	     */
101	    private static final int CITY_HARD_CAPACITY = 50;
102	
103	    /**
104	     * Soft per-city capacity: the threshold, one band below the {@link #CITY_HARD_CAPACITY hard
105	     * limit}, at which a city is treated as filling up. Counted against the owners already present
106	     * excluding the owner itself; surfaced on responses as {@code capacityWarning} for the band
107	     * between this soft threshold and the hard limit.
108	     */
109	    private static final int CITY_SOFT_CAPACITY = 40;
110	
111	    private final ClinicService clinicService;
112	
113	    private final OwnerMapper ownerMapper;
114	
115	    private final PetMapper petMapper;
116	
117	    private final VisitMapper visitMapper;
118	
119	    public OwnerRestControllerV1(ClinicService clinicService,
120	                                 OwnerMapper ownerMapper,
121	                                 PetMapper petMapper,
122	                                 VisitMapper visitMapper) {
123	        this.clinicService = clinicService;
124	        this.ownerMapper = ownerMapper;
125	        this.petMapper = petMapper;
126	        this.visitMapper = visitMapper;
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
132	        Collection<Owner> owners;
133	        if (lastName != null) {
134	            owners = this.clinicService.findOwnerByLastName(lastName);
135	        } else {
136	            owners = this.clinicService.findAllOwners();
137	        }
138	        if (owners.isEmpty()) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
147	        return withOwner(ownerId, owner ->
148	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
149	    }
150	
151	    /**
152	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
153	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
154	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
155	     */
156	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        return onFound.apply(owner);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
167	        String idempotencyKey = currentIdempotencyKey();
168	        if (idempotencyKey != null) {
169	            Integer existingId = idempotentCreates.get(idempotencyKey);
170	            if (existingId != null) {
171	                Owner existing = this.clinicService.findOwnerById(existingId);
172	                if (existing != null) {
173	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
174	                }
175	            }
176	        }
177	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
178	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
179	                && response.getBody() != null && response.getBody().getId() != null) {
180	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
181	        }
182	        return response;
183	    }
184	
185	    /**
186	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
187	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
188	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
189	     */
190	    private static String currentIdempotencyKey() {
191	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
192	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
193	            if (key != null && !key.isBlank()) {
194	                return key;
195	            }
196	        }
197	        return null;
198	    }
199	
200	    /**
201	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
202	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
203	     * identity and per-city gates are applied, the derived registration attributes are
204	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
205	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
206	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
207	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
208	     * of the create pipeline.
209	     */
210	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        if (!normalizeAndValidateFields(owner)) {
213	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
214	        }
215	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
216	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
217	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
218	        }
219	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
220	        owner.setRegistrationDate(registrationDate);
221	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
222	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
223	        }
224	        owner.setHouseholdId(householdId(owner));
225	        owner.setIdentityKey(identityKey(owner));
226	        if (isDuplicate(owner)) {
227	            return new ResponseEntity<>(HttpStatus.CONFLICT);
228	        }
229	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
230	        if (countOwnersInCity(owner.getCity()) >= CITY_HARD_CAPACITY) {
231	            return new ResponseEntity<>(HttpStatus.CONFLICT);
232	        }
233	        assignRegistrationAttributes(owner, sharesHousehold);
234	        this.clinicService.saveOwner(owner);
235	        auditOwnerCreated(owner);
236	        enqueueWelcomeNotification(owner);
237	        HttpHeaders headers = new HttpHeaders();
238	        headers.setLocation(UriComponentsBuilder.newInstance()
239	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
240	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
241	    }
242	
243	    /**
244	     * Emit the audit trail for a freshly persisted {@code owner} on the dedicated {@code AUDIT}
245	     * logger: the human-readable line followed by the structured {@link OwnerCreatedEvent}. This is
246	     * the one place a created owner's identifiers are read for the audit trail, so a change to which
247	     * identifier is audited is confined here rather than woven through the create pipeline.
248	     */
249	    private void auditOwnerCreated(Owner owner) {
250	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
251	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
252	        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
253	    }
254	
255	    /**
256	     * Enqueue the welcome notification for a freshly persisted {@code owner} on the dedicated
257	     * {@code NOTIFY} logger: one line carrying the owner's id and member id, the identifiers a
258	     * downstream notifier needs to greet the new member. Kept separate from the audit trail so the
259	     * notification concern is emitted in one place, after the owner is saved and its id is assigned.
260	     */
261	    private void enqueueWelcomeNotification(Owner owner) {
262	        NOTIFY.info("Welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
263	    }
264	
265	    /**
266	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
267	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
268	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
269	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
270	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
271	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
272	     */
273	    private boolean normalizeAndValidateFields(Owner owner) {
274	        if (!normalizeAddressFields(owner)) {
275	            return false;
276	        }
277	        if (owner.getEmail() != null) {
278	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
279	            if (!EMAIL_PATTERN.matcher(email).matches()) {
280	                return false;
281	            }
282	            if (isDisposableEmailDomain(email)) {
283	                return false;
284	            }
285	            owner.setEmail(email);
286	        }
287	        if (!isPostcodeValidForCity(owner)) {
288	            return false;
289	        }
290	        String telephone = normalizeTelephone(owner.getTelephone());
291	        if (telephone == null) {
292	            return false;
293	        }
294	        owner.setTelephone(telephone);
295	        return true;
296	    }
297	
298	    /**
299	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
300	     * returning whether the owner may proceed to creation. The structured fields are preferred when
301	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
302	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
303	     * composed value (the normalized addressLine1, with a single space and the normalized
304	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
305	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
306	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
307	     * address. This is the single place the owner's address is read, canonicalized and written back,
308	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
309	     */
310	    private boolean normalizeAddressFields(Owner owner) {
311	        String line1 = normalizeAddress(owner.getAddressLine1());
312	        if (!line1.isEmpty()) {
313	            String line2 = normalizeAddress(owner.getAddressLine2());
314	            owner.setAddressLine1(line1);
315	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
316	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
317	            return true;
318	        }
319	        String address = normalizeAddress(owner.getAddress());
320	        if (address.isEmpty()) {
321	            return false;
322	        }
323	        owner.setAddress(address);
324	        return true;
325	    }
326	
327	    /**
328	     * The domain part of {@code email} - everything after the last '@' - or {@code null} when the
329	     * value carries no '@'. The email is already normalized to lower case by the caller, so the
330	     * returned domain is lower-case and ready for a case-insensitive comparison. This is the single
331	     * place an email's domain is carved out, so the checks that compare a domain share it rather
332	     * than each re-scanning for the '@'.
333	     */
334	    private static String emailDomain(String email) {
335	        int at = email.lastIndexOf('@');
336	        return at < 0 ? null : email.substring(at + 1);
337	    }
338	
339	    /**
340	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
341	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
342	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
343	     */
344	    private static boolean isDisposableEmailDomain(String email) {
345	        String domain = emailDomain(email);
346	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
347	    }
348	
349	    /**
350	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
351	     * computed against the owner population rather than carried on the owner itself (currently the
352	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
353	     * listing intentionally omits these flags.
354	     */
355	    private OwnerDto buildOwnerDto(Owner owner) {
356	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
357	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
358	        ownerDto.setCapacityWarning(isCapacityWarning(owner));
359	        return ownerDto;
360	    }
361	
362	    /**
363	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
364	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
365	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
366	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
367	     * owners already present, before the new one is added).
368	     */
369	    private boolean isCapacityWarning(Owner owner) {
370	        long othersInCity = countOtherOwnersInCity(owner);
371	        return othersInCity >= CITY_SOFT_CAPACITY && othersInCity < CITY_HARD_CAPACITY;
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
377	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
378	        if (currentOwner == null) {
379	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
380	        }
381	        currentOwner.setAddress(ownerFieldsDto.getAddress());
382	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
383	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
384	        currentOwner.setCity(ownerFieldsDto.getCity());
385	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
386	        currentOwner.setLastName(ownerFieldsDto.getLastName());
387	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
388	        String email = ownerFieldsDto.getEmail();
389	        if (email != null) {
390	            email = email.trim().toLowerCase(Locale.ROOT);
391	            if (!EMAIL_PATTERN.matcher(email).matches()) {
392	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
393	            }
394	        }
395	        currentOwner.setEmail(email);
396	        this.clinicService.saveOwner(currentOwner);
397	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Transactional
402	    @Override
403	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
404	        return withOwner(ownerId, owner -> {
405	            owner.setDeleted(true);
406	            this.clinicService.saveOwner(owner);
407	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
408	        });
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
414	        Owner owner = this.clinicService.findOwnerById(ownerId);
415	        if (owner == null) {
416	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
417	        }
418	        HttpHeaders headers = new HttpHeaders();
419	        Pet pet = petMapper.toPet(petFieldsDto);
420	        owner.setId(ownerId);
421	        pet.setOwner(owner);
422	        pet.getType().setName(null);
423	        this.clinicService.savePet(pet);
424	        PetDto petDto = petMapper.toPetDto(pet);
425	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
426	            .buildAndExpand(pet.getId()).toUri());
427	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
428	    }
429	
430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Override
432	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
433	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
434	        if (currentOwner != null) {
435	            Pet currentPet = this.clinicService.findPetById(petId);
436	            if (currentPet != null) {
437	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
438	                currentPet.setName(petFieldsDto.getName());
439	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
440	                this.clinicService.savePet(currentPet);
441	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
442	            }
443	        }
444	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	    }
