475	
476	    /** Matches a well-formed postcode: exactly 4 digits. */
477	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
478	
479	    /**
480	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
481	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
482	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
483	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
484	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
485	     */
486	    private static boolean isPostcodeValidForCity(Owner owner) {
487	        String postcode = owner.getPostcode();
488	        if (postcode == null) {
489	            return true;
490	        }
491	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
492	            return false;
493	        }
494	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
495	        if (range == null) {
496	            return true;
497	        }
498	        int value = Integer.parseInt(postcode);
499	        return value >= range[0] && value <= range[1];
500	    }
501	
502	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
503	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
504	
505	    /**
506	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
507	     * code are kept when present; otherwise country code '+61' is assumed and a single
508	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
509	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
510	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
511	     * Returns {@code null} when the number cannot form a valid E.164 value.
512	     */
513	    private static String normalizeTelephone(String telephone) {
514	        if (telephone == null) {
515	            return null;
516	        }
517	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
518	        String e164;
519	        if (cleaned.startsWith("+")) {
520	            e164 = cleaned;
521	        } else {
522	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
523	            e164 = "+61" + national;
524	        }
525	        if (!E164_PATTERN.matcher(e164).matches()) {
526	            return null;
527	        }
528	        return hasValidNationalNumberLength(e164) ? e164 : null;
529	    }
530	
531	    /**
532	     * Whether the national number of a well-formed E.164 value has the length required for its
533	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
534	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
535	     */
536	    private static boolean hasValidNationalNumberLength(String e164) {
537	        String countryCode = Owner.countryCodeOf(e164);
538	        if (countryCode == null) {
539	            return true;
540	        }
541	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
542	    }
543	
544	    /**
545	     * Compute and assign the derived attributes carried by a newly registered owner: the member id,
546	     * household id, namesake count and household member count. Each is derived from the owner's
547	     * already-normalized fields and the existing owner population, so this must run before the owner
548	     * is saved, while the counts still exclude the owner being created.
549	     *
550	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
551	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
552	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
553	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
554	     */
555	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
556	        owner.setMemberId(generateMemberId(owner));
557	        owner.setHouseholdId(householdId(owner));
558	        owner.setNamesakeCount(countNamesakes(owner));
559	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
560	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
561	        if (declaredMember) {
562	            owner.setPossibleDuplicate(false);
563	            owner.setPossibleDuplicateOf(null);
564	        } else {
565	            assignPossibleDuplicate(owner);
566	        }
567	    }
568	
569	    /**
570	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
571	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
572	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
573	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
574	     * matching owner's id. Runs before save, against the existing owner population.
575	     */
576	    private void assignPossibleDuplicate(Owner owner) {
577	        Integer matchId = findPossibleDuplicateOf(owner);
578	        owner.setPossibleDuplicate(matchId != null);
579	        owner.setPossibleDuplicateOf(matchId);
580	    }
581	
582	    /**
583	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
584	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
585	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
586	     * with the same last name and postcode but different telephones differ in key and so match here,
587	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
588	     * the lowest id is returned. An owner without a postcode never matches.
589	     */
590	    private Integer findPossibleDuplicateOf(Owner owner) {
591	        String postcode = owner.getPostcode();
592	        if (postcode == null) {
593	            return null;
594	        }
595	        String soundex = soundex(owner.getLastName());
596	        String identityKey = owner.getIdentityKey();
597	        return this.clinicService.findAllOwners().stream()
598	            .filter(existing -> !existing.isDeleted())
599	            .filter(existing -> existing.getId() != null
600	                && postcode.equals(existing.getPostcode())
601	                && soundex(existing.getLastName()).equals(soundex)
602	                && !identityKey.equals(existing.getIdentityKey()))
603	            .map(Owner::getId)
604	            .min(Integer::compareTo)
605	            .orElse(null);
606	    }
607	
608	    /**
609	     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code derived
610	     * from the owner's postcode ({@link Owner#getRegion()}), FY the two-digit
611	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
612	     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
613	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
614	     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
615	     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
616	     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
617	     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
618	     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
619	     */
620	    private String generateMemberId(Owner owner) {
621	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
622	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
623	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
624	        String core = owner.getRegion() + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
625	        String base = core + Owner.luhnCheckDigit(core);
626	        return deduplicateMemberId(base);
627	    }
628	
629	    /**
630	     * De-duplicate a computed member id against the existing owner population: when {@code base}
631	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
632	     * {@code n} of 2 or more that yields an id no existing owner carries.
633	     */
634	    private String deduplicateMemberId(String base) {
635	        Set<String> existing = this.clinicService.findAllOwners().stream()
636	            .map(Owner::getMemberId)
637	            .filter(code -> code != null)
638	            .collect(java.util.stream.Collectors.toSet());
639	        if (!existing.contains(base)) {
640	            return base;
641	        }
642	        int n = 2;
643	        while (existing.contains(base + "-" + n)) {
644	            n++;
645	        }
646	        return base + "-" + n;
647	    }
648	
649	    /**
650	     * The number of existing owners registered in {@code city}, compared case-insensitively
651	     * with collapsed whitespace.
652	     */
653	    private int countOwnersInCity(String city) {
654	        String normalized = normalizeHouseholdField(city);
655	        return (int) this.clinicService.findAllOwners().stream()
656	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
657	            .count();
658	    }
659	
660	    /**
661	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
662	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
663	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
664	     */
665	    private long countOtherOwnersInCity(Owner owner) {
666	        String normalized = normalizeHouseholdField(owner.getCity());
667	        return this.clinicService.findAllOwners().stream()
668	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
669	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
670	            .count();
671	    }
672	
673	    /**
674	     * The effective registration date to store for a new owner: the date supplied on the request
675	     * when present, otherwise the current server date, in either case rolled forward to a business
676	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
677	     * This single point of resolution is what every registration-date-derived value (the stored
678	     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
679	     */
680	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
681	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
682	        return toBusinessDay(date);
683	    }
684	
685	    /**
686	     * The fixed list of public holidays that a registration date must not fall on. A date landing
687	     * on one of these is rolled forward, exactly as weekends are.
688	     */
689	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
690	        LocalDate.of(2026, 1, 1),
691	        LocalDate.of(2026, 1, 26),
692	        LocalDate.of(2026, 4, 25),
693	        LocalDate.of(2026, 12, 25),
694	        LocalDate.of(2026, 12, 28));
695	
696	    /**
697	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
698	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
699	     * unchanged.
700	     */
701	    private static LocalDate toBusinessDay(LocalDate date) {
702	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
703	                || PUBLIC_HOLIDAYS.contains(date)) {
704	            date = date.plusDays(1);
705	        }
706	        return date;
707	    }
708	
709	    /**
710	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
711	     * last name, compared case-insensitively.
712	     */
713	    private int countNamesakes(Owner owner) {
714	        String firstName = normalizeHouseholdField(owner.getFirstName());
715	        String lastName = normalizeHouseholdField(owner.getLastName());
716	        return (int) this.clinicService.findAllOwners().stream()
717	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
718	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
719	            .count();
720	    }
721	
722	    /**
723	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
724	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
725	     * unusually high daily signup volume.
726	     */
727	    private boolean isBulkSignupWarning() {
728	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
729	    }
730	
731	    /** The number of existing owners whose registration date is {@code date}. */
732	    private int countOwnersRegisteredOn(LocalDate date) {
733	        return (int) this.clinicService.findAllOwners().stream()
734	            .filter(existing -> date.equals(existing.getRegistrationDate()))
735	            .count();
736	    }
737	
738	    /**
739	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
740	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
741	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
742	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
743	     * the telephone is part of the key, two owners with the same last name and postcode but
744	     * different telephones resolve to different keys and are both allowed (the later one becoming a
745	     * possible duplicate rather than a hard conflict).
746	     */
747	    private static String identityKey(Owner owner) {
748	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
749	        String email = owner.getEmail() == null ? "" : owner.getEmail();
750	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
751	        return Owner.sha256HexLower(key);
752	    }
753	
754	    /**
755	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
756	     * the sole duplicate condition: the previously separate telephone, email and household checks -
757	     * including the household-duplicate check derived from the {@code householdId} - are now all
758	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
759	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
760	     */
761	    private boolean isDuplicate(Owner owner) {
762	        String key = owner.getIdentityKey();
763	        return this.clinicService.findAllOwners().stream()
764	            .filter(existing -> !existing.isDeleted())
765	            .map(Owner::getIdentityKey)
766	            .filter(existing -> existing != null)
767	            .anyMatch(key::equals);
768	    }
769	
770	    /** Common street-type abbreviations expanded during address normalization. */
771	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
772	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
773	
774	    /**
775	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
776	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
777	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
778	     * string when {@code address} is null or blank after normalization.
779	     */
780	    private static String normalizeAddress(String address) {
781	        if (address == null) {
782	            return "";
783	        }
784	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
785	        if (collapsed.isEmpty()) {
786	            return "";
787	        }
788	        StringBuilder sb = new StringBuilder(collapsed.length());
789	        for (String token : collapsed.split(" ")) {
790	            if (sb.length() > 0) {
791	                sb.append(' ');
792	            }
793	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
794	        }
795	        return sb.toString();
796	    }
797	
798	    /**
799	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
800	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
801	     */
802	    private static String normalizeHouseholdField(String value) {
803	        if (value == null) {
804	            return "";
805	        }
806	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
807	    }
808	
809	    /**
810	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
811	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
812	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
813	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
814	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
815	     * identity key and the possible-duplicate soft match compare on.
816	     */
817	    private static String soundex(String value) {
818	        if (value == null) {
819	            return "";
820	        }
821	        StringBuilder letters = new StringBuilder();
822	        for (char c : value.toCharArray()) {
823	            if (c < 128 && Character.isLetter(c)) {
824	                letters.append(Character.toUpperCase(c));
825	            }
826	        }
827	        if (letters.length() == 0) {
828	            return "";
829	        }
830	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
831	        char previous = soundexDigit(letters.charAt(0));
832	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
833	            char c = letters.charAt(i);
834	            if (c == 'H' || c == 'W') {
835	                continue;
836	            }
837	            char digit = soundexDigit(c);
838	            if (digit != '0' && digit != previous) {
839	                code.append(digit);
840	            }
841	            previous = digit;
842	        }
843	        while (code.length() < 4) {
844	            code.append('0');
845	        }
846	        return code.toString();
847	    }
848	
849	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
850	    private static char soundexDigit(char c) {
851	        switch (c) {
852	            case 'B': case 'F': case 'P': case 'V':
853	                return '1';
854	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
855	                return '2';
856	            case 'D': case 'T':
857	                return '3';
858	            case 'L':
859	                return '4';
860	            case 'M': case 'N':
861	                return '5';
862	            case 'R':
863	                return '6';
864	            default:
865	                return '0';
866	        }
867	    }
868	
869	    /**
870	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
871	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
872	     * key rather than re-derived from the underlying fields here, so the household is described in one
873	     * place and every household-keyed value stays consistent with it.
874	     */
875	    private List<Owner> findHousemates(Owner owner) {
876	        String householdId = householdId(owner);
877	        return this.clinicService.findAllOwners().stream()
878	            .filter(existing -> !existing.isDeleted())
879	            .filter(existing -> householdId(existing).equals(householdId))
880	            .toList();
881	    }
882	
883	    /**
884	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
885	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
886	     */
887	    private int countHouseholdMembers(Owner owner) {
888	        return findHousemates(owner).size() + 1;
889	    }
890	
891	    /**
892	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
893	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
894	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
895	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
896	     * applies - when the owner has no existing household member.
897	     */
898	    private Integer membershipLevelCapForHousehold(Owner owner) {
899	        OptionalInt maxLevel = findHousemates(owner).stream()
900	            .mapToInt(Owner::getMembershipLevel)
901	            .max();
902	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
903	    }
904	
905	    /**
906	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
907	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
908	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
909	     * string standing in for a missing postcode), so housemates always resolve to the same value
910	     * regardless of registration order, and owners sharing a last name and postcode share it
911	     * automatically.
912	     */
913	    private static String householdId(Owner owner) {
914	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
915	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
916	        return Owner.sha256Hex(key).substring(0, 12);
917	    }
918	}
