372	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
373	    private static int membershipLevel(int points) {
374	        if (points >= 6) {
375	            return 4;
376	        }
377	        if (points >= 4) {
378	            return 3;
379	        }
380	        if (points >= 2) {
