385	
386	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
387	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
388	    private static int capMembershipLevel(int level, Integer cap) {
389	        return cap == null ? level : Math.min(level, cap);
390	    }
391	
392	    /**
393	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
394	     * present, otherwise {@code "PHONE"}.
395	     */
396	    @Transient
397	    public String getContactPreference() {
398	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
399	    }
400	
401	    /**
402	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
403	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
404	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
405	     * date to measure against) is available.
406	     */
407	    @Transient
408	    public String getAgeBand() {
409	        if (this.birthDate == null || this.registrationDate == null) {
410	            return null;
411	        }
412	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
413	        if (age < 18) {
414	            return "MINOR";
415	        }
416	        if (age < 65) {
417	            return "ADULT";
418	        }
419	        return "SENIOR";
420	    }
421	
422	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
423	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
424	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
425	        "NSW", new int[] {2000, 2099},
426	        "VIC", new int[] {3000, 3099},
427	        "QLD", new int[] {4000, 4099});
428	
429	    /**
430	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
431	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
432	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
433	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
434	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
435	     */
436	    @Transient
437	    public String getRegion() {
438	        String byPostcode = regionForPostcode(this.postcode);
439	        if (byPostcode != null) {
440	            return byPostcode;
441	        }
442	        if ("Sydney".equals(this.city)) {
443	            return "NSW";
444	        }
445	        if ("Melbourne".equals(this.city)) {
446	            return "VIC";
447	        }
448	        if ("Brisbane".equals(this.city)) {
449	            return "QLD";
450	        }
451	        return "UNKNOWN";
452	    }
453	
454	    /** The region codes a {@link #getMemberId() member id} can begin with, matched to recover the
455	     *  leading REGION segment of a '<REGION><FY><HASH8><CHK>' member id: the known postcode regions
456	     *  plus the {@code "UNKNOWN"} fallback. */
457	    private static final Set<String> LOCALITY_REGIONS = Set.of("NSW", "VIC", "QLD", "UNKNOWN");
458	
459	    /**
460	     * The owner's locality, derived on read from the region-and-hash {@link #getMemberId() member
461	     * id}: the leading REGION segment of the member id ('<REGION><FY><HASH8><CHK>'). Falls back to
462	     * the owner's {@link #getRegion() region} when no member id has been assigned yet.
463	     */
464	    @Transient
465	    public String getLocality() {
466	        String region = regionOfMemberId(this.memberId);
467	        return region != null ? region : getRegion();
468	    }
469	
470	    /** The leading REGION segment of a '<REGION><FY><HASH8><CHK>' {@code memberId}, i.e. the known
471	     *  region code ({@link #LOCALITY_REGIONS}) it starts with, or {@code null} when {@code memberId}
472	     *  is null or starts with no known region. The remaining segments (FY, HASH8, CHK) are digits and
473	     *  upper-hex, so a region prefix is recovered unambiguously. */
474	    private static String regionOfMemberId(String memberId) {
475	        if (memberId == null) {
476	            return null;
477	        }
478	        for (String region : LOCALITY_REGIONS) {
479	            if (memberId.startsWith(region)) {
480	                return region;
481	            }
482	        }
483	        return null;
484	    }
485	
486	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
487	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
488	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
489	        "NSW", "Australia/Sydney",
490	        "VIC", "Australia/Melbourne",
491	        "QLD", "Australia/Brisbane");
492	
493	    /**
494	     * The owner's timezone, derived on read as the IANA name for the owner's
495	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
496	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
497	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
498	     * the table (e.g. {@code UNKNOWN}).
499	     */
500	    @Transient
501	    public String getTimezone() {
502	        return timezoneForRegion(getLocality());
503	    }
504	
505	    /**
506	     * The owner's segment, derived on read as {@code "<TIER>_<AREA>"}: one of {@code "PREMIUM_METRO"},
507	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. TIER is
508	     * {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is 3 or more, otherwise
509	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the {@link #getLocality() locality} is a known
510	     * region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code "REGIONAL"}.
511	     */
512	    @Transient
513	    public String getOwnerSegment() {
514	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
515	        String area = REGION_POSTCODE_RANGES.containsKey(getLocality()) ? "METRO" : "REGIONAL";
516	        return tier + "_" + area;
517	    }
518	
519	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
520	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
521	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
522	    public static String timezoneForRegion(String region) {
523	        return REGION_TIMEZONES.get(region);
524	    }
525	
526	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
527	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
528	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
529	    public static int[] postcodeRangeForRegion(String region) {
530	        return REGION_POSTCODE_RANGES.get(region);
531	    }
532	
533	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
534	     *  absent, not a 4-digit value, or in no known range. */
535	    private static String regionForPostcode(String postcode) {
536	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
537	            return null;
538	        }
539	        int value = Integer.parseInt(postcode);
540	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
541	            int[] range = entry.getValue();
542	            if (value >= range[0] && value <= range[1]) {
543	                return entry.getKey();
544	            }
545	        }
546	        return null;
547	    }
548	
549	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
550	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
551	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
552	     *  {@code +1}), so a number matches at most one. */
553	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
554	        "+61", 9, "+1", 10);
555	
556	    /**
557	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
558	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
559	     * to the raw value when it is {@code null} or begins with no recognised country code.
560	     */
561	    @Transient
562	    public String getTelephoneDisplay() {
563	        if (this.telephone == null) {
564	            return null;
565	        }
566	        String countryCode = countryCodeOf(this.telephone);
567	        if (countryCode == null) {
568	            return this.telephone;
569	        }
570	        String national = this.telephone.substring(countryCode.length());
571	        StringBuilder grouped = new StringBuilder(countryCode);
572	        for (int i = 0; i < national.length(); i++) {
573	            if (i % 3 == 0) {
574	                grouped.append(' ');
575	            }
576	            grouped.append(national.charAt(i));
577	        }
578	        return grouped.toString();
579	    }
580	
581	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
582	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
583	    public static String countryCodeOf(String telephone) {
584	        if (telephone == null) {
585	            return null;
586	        }
587	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
588	            if (telephone.startsWith(countryCode)) {
589	                return countryCode;
590	            }
591	        }
592	        return null;
593	    }
594	
595	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
596	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
597	     *  {@code +1 => 10}). */
598	    public static Integer nationalNumberLength(String countryCode) {
599	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
600	    }
601	
602	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
603	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
604	     *  digit-free value yields {@code 0}. Used by the controller to compute the CHK segment stamped
605	     *  into an owner's member id, so the Luhn rule lives here once and is not duplicated. */
606	    public static int luhnCheckDigit(String value) {
607	        int sum = 0;
608	        boolean doubling = true;
609	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
610	            char c = value.charAt(i);
611	            if (c < '0' || c > '9') {
612	                continue;
613	            }
614	            int digit = c - '0';
615	            if (doubling) {
616	                digit *= 2;
617	                if (digit > 9) {
618	                    digit -= 9;
619	                }
620	            }
621	            sum += digit;
622	            doubling = !doubling;
623	        }
624	        return (10 - (sum % 10)) % 10;
625	    }
626	
627	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
628	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
629	    public static String sha256Hex(String input) {
630	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
631	    }
632	
633	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
634	    public static String sha256HexLower(String input) {
635	        try {
636	            byte[] digest = MessageDigest.getInstance("SHA-256")
637	                .digest(input.getBytes(StandardCharsets.UTF_8));
638	            StringBuilder sb = new StringBuilder(digest.length * 2);
639	            for (byte b : digest) {
640	                sb.append(String.format("%02x", b));
641	            }
642	            return sb.toString();
643	        }
644	        catch (NoSuchAlgorithmException e) {
645	            throw new IllegalStateException("SHA-256 not available", e);
646	        }
647	    }
648	
649	    protected Set<Pet> getPetsInternal() {
650	        if (this.pets == null) {
651	            this.pets = new HashSet<>();
652	        }
653	        return this.pets;
654	    }
655	
656	    protected void setPetsInternal(Set<Pet> pets) {
657	        this.pets = pets;
658	    }
659	
660	    public List<Pet> getPets() {
661	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
662	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
663	        return Collections.unmodifiableList(sortedPets);
664	    }
665	
666	    public void setPets(List<Pet> pets) {
667	        this.pets = new HashSet<>(pets);
668	    }
669	
670	    public void addPet(Pet pet) {
671	        getPetsInternal().add(pet);
672	        pet.setOwner(this);
673	    }
674	
675	    /**
676	     * Return the Pet with the given name, or null if none found for this Owner.
677	     *
678	     * @param name to test
679	     * @return true if pet name is already in use
680	     */
681	    public Pet getPet(String name) {
682	        return getPet(name, false);
683	    }
684	
685	    /**
686	     * Return the Pet with the given name, or null if none found for this Owner.
687	     *
688	     * @param name to test
689	     * @return true if pet name is already in use
690	     */
691	    public Pet getPet(String name, boolean ignoreNew) {
692	        name = name.toLowerCase();
693	        for (Pet pet : getPetsInternal()) {
694	            if (!ignoreNew || !pet.isNew()) {
695	                String compName = pet.getName();
696	                compName = compName.toLowerCase();
697	                if (compName.equals(name)) {
698	                    return pet;
699	                }
700	            }
701	        }
702	        return null;
703	    }
704	
705	    public Pet getPet(Integer petId) {
706	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
707	    }
708	
709	    @Override
710	    public String toString() {
711	        return new ToStringCreator(this)
712	
713	            .append("id", this.getId())
714	            .append("new", this.isNew())
715	            .append("lastName", this.getLastName())
716	            .append("firstName", this.getFirstName())
717	            .append("address", this.address)
718	            .append("city", this.city)
719	            .append("telephone", this.telephone)
720	            .toString();
721	    }
722	}
